const notice=document.querySelector('[data-privacy-notice]');if(notice){try{if(localStorage.getItem('csg-privacy-notice-v1')==='acknowledged')notice.hidden=true;}catch(e){}const dismiss=notice.querySelector('[data-dismiss-privacy]');if(dismiss)dismiss.addEventListener('click',()=>{notice.hidden=true;try{localStorage.setItem('csg-privacy-notice-v1','acknowledged')}catch(e){}})}
const cloudStage=document.querySelector('.hero-cloud-stage');
if(cloudStage){
  const clamp=(n,min,max)=>Math.max(min,Math.min(max,n));
  const cloudItems=cloudStage.querySelectorAll('[data-cloud]');
  let held=null;
  function position(cloud,x,y){
    const nx=clamp(x,-230,230),ny=clamp(y,-130,130);
    cloud.dataset.x=String(nx);cloud.dataset.y=String(ny);
    cloud.style.transform='translate('+nx+'px,'+ny+'px)';
  }
  cloudItems.forEach(cloud=>{
    cloud.addEventListener('pointerdown',e=>{
      if(held || (e.pointerType==='mouse' && e.button!==0))return;
      const rect=cloudStage.getBoundingClientRect();
      held={cloud,id:e.pointerId,x:e.clientX,y:e.clientY,
        baseX:Number(cloud.dataset.x||0),baseY:Number(cloud.dataset.y||0),
        scaleX:1200/Math.max(rect.width,1),scaleY:630/Math.max(rect.height,1)};
      cloud.classList.add('is-dragging');
      cloud.setPointerCapture?.(e.pointerId);
      if(e.pointerType==='mouse')e.preventDefault();
    });
    cloud.addEventListener('pointermove',e=>{
      if(!held||held.cloud!==cloud||held.id!==e.pointerId)return;
      position(cloud,held.baseX+(e.clientX-held.x)*held.scaleX,
        held.baseY+(e.clientY-held.y)*held.scaleY);
    });
    const finish=e=>{
      if(!held||held.cloud!==cloud||held.id!==e.pointerId)return;
      cloud.classList.remove('is-dragging');
      held=null;
    };
    cloud.addEventListener('pointerup',finish);
    cloud.addEventListener('pointercancel',finish);
    cloud.addEventListener('lostpointercapture',finish);
    cloud.addEventListener('keydown',e=>{
      const arrows={ArrowLeft:[-14,0],ArrowRight:[14,0],ArrowUp:[0,-14],ArrowDown:[0,14]};
      if(arrows[e.key]){
        e.preventDefault();
        const delta=arrows[e.key];
        position(cloud,Number(cloud.dataset.x||0)+delta[0],
          Number(cloud.dataset.y||0)+delta[1]);
      }else if(e.key==='Home'){
        e.preventDefault();position(cloud,0,0);
      }
    });
  });
}
